 if typ=='STOCK_SOLUTION':record['solution_type']=solution
 if parts:
  record['components']=parts;record['component_assertion']={'method':method,'completeness':'UNKNOWN','evidence':[{'evidence_type':'RECIPE_SOURCE' if method=='RECIPE_TRANSCRIPTION' else 'SOURCE_LABEL','source':u,'source_record':label,'notes':scope} for u in source_urls]}
